<?php require_once __DIR__.'/bootstrap.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){header('Location: index.php');exit;}$stmt=$pdo->prepare('SELECT id,name,category,price,stock FROM products WHERE id = ?');$stmt->execute([$id]);$product=$stmt->fetch();if(!$product){flash('error','Produk tidak ditemukan.');header('Location: index.php');exit;}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$category=trim($_POST['category']??'');$price=trim($_POST['price']??'');$stock=trim($_POST['stock']??'');$product['name']=$name;$product['category']=$category;$product['price']=$price;$product['stock']=$stock;if(mb_strlen($name)<3)$errors[]='Nama produk minimal 3 karakter.';if($category==='')$errors[]='Kategori wajib diisi.';if(!is_numeric($price)||(float)$price<=0)$errors[]='Harga harus lebih besar dari 0.';if(filter_var($stock,FILTER_VALIDATE_INT)===false||(int)$stock<0)$errors[]='Stok harus bilangan bulat 0 atau lebih.';if(!$errors){$check=$pdo->prepare('SELECT id FROM products WHERE name = ? AND id <> ? LIMIT 1');$check->execute([$name,$id]);if($check->fetch())$errors[]='Nama produk sudah digunakan. Gunakan nama yang unik.';}if(!$errors){$update=$pdo->prepare('UPDATE products SET name=?,category=?,price=?,stock=? WHERE id=?');try{$update->execute([$name,$category,(float)$price,(int)$stock,$id]);flash('success','Produk berhasil diperbarui.');header('Location: index.php');exit;}catch(PDOException $e){$errors[]='Produk gagal diperbarui.';}}}?>
<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Edit Produk — MELORA MART</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="topbar"><div class="container nav-wrap"><a class="brand" href="index.php">MELORA MART</a></div></header><main class="container form-page"><a class="back" href="index.php">← Kembali ke daftar</a><div class="form-card"><p class="eyebrow">UPDATE</p><h1>Edit Produk</h1><p class="subtitle">Perbarui data produk berdasarkan ID yang dipilih.</p><?php if($errors):?><div class="alert error"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" novalidate><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Nama Produk <input type="text" name="name" value="<?=e((string)$product['name'])?>" minlength="3" required></label><label>Kategori <input type="text" name="category" value="<?=e((string)$product['category'])?>" required></label><label>Harga <input type="number" name="price" value="<?=e((string)$product['price'])?>" min="0.01" step="0.01" required></label><label>Stok <input type="number" name="stock" value="<?=e((string)$product['stock'])?>" min="0" step="1" required></label><div class="form-actions"><a class="btn btn-muted" href="index.php">Batal</a><button class="btn btn-primary" type="submit">Simpan Perubahan</button></div></form></div></main></body></html>
